import cv2,numpy as np
im=cv2.imread('first_frame.png')
# try Hough at native scale and ball crop
for region in [(115,85,185,115),(120,90,175,110)]:
 x1,y1,x2,y2=region;g=cv2.cvtColor(im[y1:y2,x1:x2],cv2.COLOR_BGR2GRAY)
 for p2 in [4,5,6,7,8,9,10]:
  c=cv2.HoughCircles(g,cv2.HOUGH_GRADIENT,dp=1,minDist=8,param1=70,param2=p2,minRadius=4,maxRadius=9)
  if c is not None: print(region,p2,[(round(x+x1,1),round(y+y1,1),round(r,1)) for x,y,r in c[0]])
PY"
